import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        long k = nextLong();
        int n = s.length();
        long bad = 0;
        for (int i = 0; i < n; i++)
            if (s.charAt(i) != (i % 2 == 0 ? 'a' : 'b')) bad++;
        if (Math.min(bad, n - bad) <= k) {
            System.out.println(1);
            return;
        }
        int[] runs = new int[n];
        int count = 0, length = 1;
        for (int i = 1; i < n; i++) {
            if (s.charAt(i) == s.charAt(i - 1)) length++;
            else {
                runs[count++] = length;
                length = 1;
            }
        }
        runs[count++] = length;
        long lo = 2, hi = n;
        while (lo < hi) {
            long mid = (lo + hi) / 2, need = 0;
            for (int i = 0; i < count; i++) need += runs[i] / (mid + 1); // flips to cap a run at mid
            if (need <= k) hi = mid;
            else lo = mid + 1;
        }
        System.out.println(lo);
    }
}

